import numpy as np
import torch
import torch.nn as nn
from sklearn.base import BaseEstimator, RegressorMixin

class _Block(nn.Module):
    def __init__(self, w, p):
        super().__init__()
        self.net = nn.Sequential(nn.LayerNorm(w), nn.Linear(w, w), nn.GELU(), nn.Dropout(p), nn.Linear(w, w))
    def forward(self, x):
        return x + self.net(x)

class _Net(nn.Module):
    def __init__(self, d_in, d_out, w, blocks, p):
        super().__init__()
        self.inp = nn.Linear(d_in, w)
        self.blocks = nn.Sequential(*[_Block(w, p) for _ in range(blocks)])
        self.out = nn.Sequential(nn.LayerNorm(w), nn.Linear(w, d_out))
    def forward(self, x):
        return self.out(self.blocks(self.inp(x)))

class NoisyResMLPEnsemble(BaseEstimator, RegressorMixin):
    def __init__(self, width=512, blocks=3, noise_std=0.05, epochs=200, lr=1e-3, weight_decay=1e-4, n_models=3, batch_size=128, dropout=0.05, seed=0):
        self.width = width; self.blocks = blocks; self.noise_std = noise_std; self.epochs = epochs
        self.lr = lr; self.weight_decay = weight_decay; self.n_models = n_models
        self.batch_size = batch_size; self.dropout = dropout; self.seed = seed
    def _train_one(self, X, Y, s):
        torch.manual_seed(s)
        rng = np.random.RandomState(s)
        n = X.shape[0]
        idx = rng.permutation(n)
        nv = max(1, int(0.1 * n))
        vi, ti = idx[:nv], idx[nv:]
        Xt, Yt, Xv, Yv = X[ti], Y[ti], X[vi], Y[vi]
        net = _Net(X.shape[1], Y.shape[1], self.width, self.blocks, self.dropout)
        opt = torch.optim.AdamW(net.parameters(), lr=self.lr, weight_decay=self.weight_decay)
        steps = self.epochs * int(np.ceil(len(ti) / self.batch_size))
        sch = torch.optim.lr_scheduler.OneCycleLR(opt, max_lr=self.lr, total_steps=steps)
        best, best_state, bad = 1e18, None, 0
        for ep in range(self.epochs):
            net.train()
            perm = torch.randperm(len(ti))
            for i in range(0, len(ti), self.batch_size):
                b = perm[i:i + self.batch_size]
                xb = Xt[b] + self.noise_std * torch.randn_like(Xt[b])
                loss = ((net(xb) - Yt[b]) ** 2).mean()
                opt.zero_grad(); loss.backward(); opt.step(); sch.step()
            net.eval()
            with torch.no_grad():
                vl = ((net(Xv) - Yv) ** 2).mean().item()
            if vl < best - 1e-6:
                best = vl; bad = 0
                best_state = {k: v.clone() for k, v in net.state_dict().items()}
            else:
                bad += 1
                if bad >= 30:
                    break
        net.load_state_dict(best_state)
        net.eval()
        return net
    def fit(self, X, y):
        torch.set_num_threads(1)
        X = torch.tensor(np.asarray(X), dtype=torch.float32)
        Y = np.asarray(y, dtype=np.float32)
        self._1d = Y.ndim == 1
        if self._1d:
            Y = Y[:, None]
        Y = torch.tensor(Y)
        self.models_ = [self._train_one(X, Y, self.seed * 100 + k) for k in range(self.n_models)]
        return self
    def predict(self, X):
        X = torch.tensor(np.asarray(X), dtype=torch.float32)
        with torch.no_grad():
            P = np.mean([m(X).numpy() for m in self.models_], axis=0)
        return P[:, 0] if self._1d else P

def build_model(params: dict, task: str, seed: int):
    keys = ['width', 'blocks', 'noise_std', 'epochs', 'lr', 'weight_decay', 'n_models', 'batch_size', 'dropout']
    kw = {k: params[k] for k in keys if k in params}
    return NoisyResMLPEnsemble(seed=seed, **kw)

import numpy as np
from sklearn.base import BaseEstimator, RegressorMixin
from sklearn.kernel_ridge import KernelRidge
from sklearn.preprocessing import StandardScaler

B = [0, 1, 2, 3, 5, 6, 7, 8]
POS = {v: i for i, v in enumerate(B)}
EDGES = [(0,1),(1,2),(3,4),(4,5),(6,7),(7,8),(0,3),(3,6),(1,4),(4,7),(2,5),(5,8)]
EIDX = {}
for k, (a, b) in enumerate(EDGES):
    EIDX[(a, b)] = k
    EIDX[(b, a)] = k
NBRS = {v: sorted([b for (a, b) in EDGES if a == v] + [a for (a, b) in EDGES if b == v]) for v in range(9)}
EPS = 1e-4

def _phys_features(X):
    X = np.asarray(X, dtype=float)
    n = X.shape[0]
    rows = []
    rhs = []
    logp_feats = []
    for x in B:
        nb = NBRS[x]
        ps = []
        for y in nb:
            if y == 4:
                ps.append(None)
            else:
                ps.append(X[:, POS[x] * 8 + POS[y]])
        obs_sum = sum(p for p in ps if p is not None)
        ps = [np.clip(1.0 - obs_sum, EPS, 1.0) if p is None else np.clip(p, EPS, 1.0) for p in ps]
        lps = np.stack([np.log(p) for p in ps], axis=1)
        logp_feats.append(lps)
        lmean = lps.mean(axis=1, keepdims=True)
        d = len(nb)
        for j, y in enumerate(nb):
            r = np.zeros(12)
            r[EIDX[(x, y)]] += 1.0
            for z in nb:
                r[EIDX[(x, z)]] -= 1.0 / d
            rows.append(r)
            rhs.append(lps[:, j] - lmean[:, 0])
    A = np.array(rows)
    Bm = np.stack(rhs, axis=1)
    Ap = np.linalg.pinv(A)
    logw = Bm @ Ap.T
    logp = np.concatenate(logp_feats, axis=1)
    return np.concatenate([logw, np.exp(logw), logp], axis=1)

class PhysKRR(BaseEstimator, RegressorMixin):
    def __init__(self, alpha=1e-3, gamma=0.02):
        self.alpha = alpha
        self.gamma = gamma
    def fit(self, X, y):
        F = _phys_features(X)
        self.sc_ = StandardScaler().fit(F)
        self.m_ = KernelRidge(kernel='rbf', alpha=self.alpha, gamma=self.gamma)
        self.m_.fit(self.sc_.transform(F), y)
        return self
    def predict(self, X):
        return self.m_.predict(self.sc_.transform(_phys_features(X)))

def build_model(params, task, seed):
    return PhysKRR(alpha=float(params.get('alpha', 1e-3)), gamma=float(params.get('gamma', 0.02)))

